    id: 'caspian-sea',
    type: 'sea',
    name: '里海',
    labelPos: [51, 40],
    importance: 2,
    description: '里海是世界上最大的湖泊（虽是海），面积约 37 万平方公里。地处欧洲和亚洲的交界，被俄罗斯、哈萨克斯坦、土库曼斯坦、伊朗、阿塞拜疆五国环绕。富含石油、天然气和鱼类资源（鲟鱼鱼子酱）。里海沿岸有巴库（阿塞拜疆首都）等重要城市。',
    imageUrl: 'https://tse1.mm.bing.net/th?q=caspian%20sea%20sunset&w=800&h=450&c=7&p=0',
    imageCredit: 'Bing 图片搜索',
    facts: [
      { label: '类型', value: '世界上最大的内陆湖' },
      { label: '面积', value: '约 37.1 万平方公里' },
      { label: '最大深度', value: '约 1025 米' },
      { label: '盐度', value: '约 1/3（约 12.5‰）' },
      { label: '沿岸国家', value: '俄罗斯、哈萨克斯坦、土库曼斯坦、伊朗、阿塞拜疆' },
      { label: '重要资源', value: '石油、天然气、鲟鱼鱼子酱' },
    ],
    sections: [
      { type: 'paragraph', heading: '世界最大湖', body: '里海（Caspian Sea）虽称"海"，实为**世界上最大的内陆湖**——面积约 37.1 万平方公里（接近波罗的海）。**它与地中海、黑海原本同属古特提斯海**，后因地壳抬升被隔离。' },
      { type: 'paragraph', heading: '油气宝库', body: '里海地区是**21 世纪重要的油气新区**——哈萨克斯坦、俄罗斯的阿斯特拉罕州、土库曼斯坦都在此开发油气。储量虽不如波斯湾，但**战略位置关键**。' },
      { type: 'callout', heading: '鱼子酱故乡', body: '里海是世界**85% 鲟鱼鱼子酱**的产地——伊朗、俄罗斯是主要供应国。但**过度捕捞**使野生鲟鱼濒临灭绝，养殖鱼子酱成为新趋势。', variant: 'warning' },
      { type: 'list', heading: '主要支流', items: [
          '伏尔加河（注入北岸，世界最长内陆河流）',
          '乌拉尔河',
          '库拉河',
          '阿特拉克河',
          '锡尔河（部分经咸海系统）',
      ] },
      { type: 'paragraph', heading: '法律地位争议', body: '里海周边 5 国对其法律地位争议多年——**是湖还是海**决定了资源分配原则。2018 年公约确认其"内陆水体"地位，但仍存争议。' },
      { type: 'quote', text: '"Sea or lake, the Caspian has always been coveted."', cite: 'Caspian Sea: A Quest for the Future' },
    ],
