    description: '加勒比海位于中美洲、南美洲和西印度群岛之间，面积约 275 万平方公里，最大深度 7686 米（开曼海沟）。1492 年哥伦布在此登陆，开启大航海时代。著名的海盗活动、加勒比海地区丰富的珊瑚礁、玛雅文明遗址都使这片海域充满传奇色彩。',
