    description: '洞庭湖位于湖南省北部，长江中游"云梦泽"古遗迹，长江流域最重要的调蓄湖泊之一，面积约 2820 平方公里（汛期 4000+）。湘江、资江、沅江、澧水在此汇入长江。"八百里洞庭"——李白、刘禹锡、范仲淹（"先天下之忧而忧，后天下之乐而乐"）、孟浩然等都留下名篇。岳阳楼、君山、屈子祠等历史名胜位于湖滨。',
    imageUrl: 'https://tse1.mm.bing.net/th?q=dongting%20lake%20china%20yueyang%20tower&w=800&h=450&c=7&p=0',
    imageCredit: 'Bing 图片搜索',
    facts: [
      { label: '类型', value: '吞吐型淡水湖' },
      { label: '面积', value: '约 2625 平方公里（丰水期 3900+）' },
      { label: '位置', value: '中国·湖南省' },
      { label: '地位', value: '中国第二大淡水湖' },
      { label: '支流', value: '湘江、资江、沅江、澧江' },
      { label: '文化地位', value: '屈原投江、岳阳楼记' },
    ],
    sections: [
      { type: 'paragraph', heading: '楚辞之源', body: '洞庭湖（Lake Dongting）是**中国第二大淡水湖**——屈原《九歌》《离骚》中多次提及。**楚辞**成为中华文学的源头之一。' },
      { type: 'paragraph', heading: '岳阳楼记', body: '湖东的**岳阳楼**因范仲淹《岳阳楼记》"先天下之忧而忧，后天下之乐而乐"闻名——此文是**宋代士大夫精神的最高表达**。' },
      { type: 'callout', heading: '八百里洞庭', body: '古时洞庭湖号称**八百里**——**实际明清时期面积约 6000 平方公里**。**现代洞庭湖萎缩至约 2625 平方公里**（丰水期）。', variant: 'warning' },
      { type: 'list', heading: '周边重要', items: [
          '岳阳楼（江南三大名楼之一）',
          '君山岛（洞庭山、湘妃竹）',
          '屈子祠（汨罗江畔）',
          '桃花源（常德，《桃花源记》原型）',
      ] },
      { type: 'paragraph', heading: '生态萎缩', body: '**围湖造田**导致洞庭湖面积从 6000 平方公里缩小到 2625 平方公里。' },
      { type: 'quote', text: '予观夫巴陵胜状，在洞庭一湖。', cite: '范仲淹《岳阳楼记》' },
    ],
