    labelPos: [50, 41],
    importance: 3,
    description: '里海位于欧洲和亚洲的交界处，是世界上最大的湖泊，面积约 37.1 万平方公里（约为中国渤海的 90 倍）。古称"里海"（里是"里"，半湖半海之意），现由俄罗斯、哈萨克斯坦、土库曼斯坦、伊朗、阿塞拜疆 5 国共有。湖中石油、天然气资源丰富，"里海石油"是世界能源市场重要组成。湖岸古城有巴库（阿塞拜疆）。古希腊时期是重要贸易节点。',
    imageUrl: 'https://tse1.mm.bing.net/th?q=caspian%20sea%20baku&w=800&h=450&c=7&p=0',
    imageCredit: 'Bing 图片搜索',
    facts: [
      { label: '类型', value: '内陆湖（世界最大）' },
      { label: '面积', value: '约 37.1 万平方公里' },
      { label: '深度', value: '最大 1025 米' },
      { label: '横跨国家', value: '5 国' },
      { label: '特点', value: '咸水湖' },
      { label: '意义', value: '世界最大咸水湖' },
    ],
    sections: [
      { type: 'paragraph', heading: '世界最大湖', body: '里海（Caspian Sea）位于欧洲和亚洲交界处，面积约 37.1 万平方公里，是**世界上最大的湖泊**——约为中国渤海的 90 倍。由**俄罗斯、哈萨克斯坦、土库曼斯坦、伊朗、阿塞拜疆**5 国共有。' },
      { type: 'paragraph', heading: '古代贸易', body: '里海是**古丝绸之路的重要节点**——**希腊、波斯、阿拉伯**商人通过里海转运货物。**古代里海**的鱼（里海鲟鱼）专供**罗马帝国贵族**。**中世纪**阿拉伯人控制里海北岸，**蒙古帝国**通过里海征服伊朗。' },
      { type: 'callout', heading: '石油海', body: '里海蕴藏**丰富的石油、天然气**——仅次于波斯湾。**巴库**（阿塞拜疆）是里海石油城，1901 年首次产油（比沙特早 30 年）。**2010 年代**以来，**哈萨克斯坦、阿塞拜疆**通过 BTC（巴库-第比利斯-杰伊汉）输油管道将里海石油输送至地中海。', variant: 'success' },
      { type: 'list', heading: '主要港口', items: [
          '巴库（阿塞拜疆）',
          '阿克套（哈萨克斯坦）',
          '马哈奇卡拉（俄罗斯）',
          '土库曼巴希（土库曼斯坦）',
          '安扎利港（伊朗）',
      ] },
      { type: 'paragraph', heading: '生态危机', body: '里海面临**海平面上升**问题——1978-1995 年下降 2.5 米（灌溉截水），1996 年以来快速上升（伏尔加河流量增加），200 年间**最大增幅 3 米**。**里海鲟鱼**（鱼子酱）濒临灭绝。' },
      { type: 'quote', text: '"Caspian" — 来自古代里海西南岸的 Caspi 部族。', cite: '古典地理学命名' },
    ],
