    description: '坦噶尼喀湖位于东非大裂谷中，是世界第二深的湖泊（最大深度 1470 米），长度约 673 公里、宽度平均 50 公里，面积约 3.27 万平方公里。由坦桑尼亚、刚果民主共和国、布隆迪、赞比亚 4 国共有。湖中栖息着约 200 种特有鱼类（慈鲷科），是研究生物进化的活博物馆。湖名来自班图语"坦噶尼喀"，意为"汇合"。',
