    description: '奥涅加湖位于俄罗斯卡累利阿地区，是欧洲第二大湖泊，面积约 9894 平方公里。湖中基日岛（Кижи）有著名的 22 圆顶木结构教堂群（18-19 世纪建造），1990 年列入联合国世界文化遗产。',
