    id: 'geneva',
    type: 'lake',
    name: '日内瓦湖',
    labelPos: [6.55, 46.45],
    importance: 1,
    description: '日内瓦湖（莱芒湖）位于瑞士与法国交界，是西欧最大的湖泊，面积约 580 平方公里，最深处 310 米。日内瓦、洛桑、蒙特勒等城市分布湖岸。新石器时代起就有人居住湖中"湖居柱屋"。日内瓦是国际红十字会、联合国欧洲总部所在地，许多重要国际条约在此签署。',
    imageUrl: 'https://tse1.mm.bing.net/th?q=lake%20geneva%20switzerland&w=800&h=450&c=7&p=0',
    imageCredit: 'Bing 图片搜索',
