    name: '长江',
    labelPos: [111, 30],
    importance: 3,
    description: '长江（扬子江）长约 6300 公里，是亚洲第一长河、世界第三长河，发源于青藏高原唐古拉山，注入东海。流经青、藏、川、滇、渝、鄂、湘、赣、皖、苏、沪 11 省市区，是中华文明的重要摇篮。三峡、葛洲坝水利枢纽、上海港、南京、武汉、重庆等沿河城市见证了中华民族的兴衰。',
