    name: '大分水岭',
    labelPos: [148, -25],
    importance: 1,
    description: '大分水岭位于澳大利亚东部，长约 3500 公里，平均海拔 1000 米，最高峰科修斯科山（2228 米）。是大堡礁山脉的一部分，分隔了太平洋水系和印度洋水系。澳大利亚东部沿海城市（悉尼、墨尔本、布里斯班）都位于其东侧。',
