    description: '秦岭是中国南北地理分界线（与淮河合称"秦岭-淮河线"），东西绵延 1600 多公里，是亚热带与暖温带的天然界线，也是长江流域与黄河流域的分水岭。最高峰太白山（3767 米）。汉唐时期，秦岭是关中平原（长安）与汉中/巴蜀之间的天然屏障，发生过无数次军事对峙（暗度陈仓、诸葛亮北伐等）。',
